1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single derived identity of an owner: the SHA-256 hex digest over the owner's
9	 * normalized telephone, lower-cased email and the {@link Soundex} code of its last name,
10	 * joined by {@code '|'}. The telephone and email are already canonical by the time a key is
11	 * built — the create steps normalize them, and stored owners hold the normalized values —
12	 * and the email is lower-cased again here so the key is stable regardless.
13	 *
14	 * <p>This is the identity that duplicate detection keys off: a create whose key matches a
15	 * non-deleted owner's is a 409 (see
16	 * {@link org.springframework.samples.petclinic.rest.function.owner.EnsureUniqueIdentity}).
17	 * The same value is exposed on the response mapper for callers.
18	 */
19	public final class IdentityKey {
20	
21	    private IdentityKey() {
22	    }
23	
24	    /** The identity key for the given owner, from its stored telephone, email and last name. */
25	    public static String of(Owner owner) {
26	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
27	    }
28	
29	    /**
30	     * The identity key for the given parts: the SHA-256 hex digest of
31	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A null or
32	     * blank telephone or email contributes an empty segment and a blank last name an empty
33	     * Soundex, so an owner missing one still has a well-formed 64-hex key.
34	     */
35	    public static String of(String telephone, String email, String lastName) {
36	        return Sha256.hex(orEmpty(telephone) + '|' + lowerEmail(email) + '|' + Soundex.of(lastName));
37	    }
38	
39	    private static String lowerEmail(String email) {
40	        return orEmpty(email).toLowerCase(Locale.ROOT);
41	    }
42	
43	    private static String orEmpty(String value) {
44	        return (value == null || value.isBlank()) ? "" : value;
45	    }
46	}
