1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
5	 * characters are ignored, so a formatted code such as {@code LON-SMI-0007} is checked on
6	 * its digits alone. The rightmost digit is doubled first, each doubled value above 9 has 9
7	 * subtracted, and the check digit is the amount that rounds the running total up to the
8	 * next multiple of ten.
9	 */
10	public final class Luhn {
11	
12	    private Luhn() {
13	    }
14	
15	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
16	    public static int checkDigit(String value) {
17	        int sum = 0;
18	        boolean doubleDigit = true;
19	        for (int i = value.length() - 1; i >= 0; i--) {
20	            char c = value.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (doubleDigit) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            doubleDigit = !doubleDigit;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
