12	/**
13	 * Assigns a newly built owner its {@code customerCode}, formatted {@code <REGION>-<HASH8>}
14	 * where REGION is the owner's region (derived from its postcode, see {@link OwnerRegion})
15	 * and HASH8 the first 8 upper-case hex characters of SHA-256 over the normalized telephone
16	 * concatenated with the last name (e.g. {@code NSW-1A2B3C4D}). Runs after
17	 * {@link NormalizeOwnerTelephone} (so the telephone is canonical) and before
18	 * {@link SaveOwner}, mutating the built owner in place so the code is stored and returned
19	 * with the owner. When the computed code collides with an existing owner's customerCode it
20	 * is de-duplicated by appending {@code -<n>} (smallest n of 2 or more that is unique); the
21	 * new owner is not yet persisted here, so it never collides with itself.
22	 */
23	public class AssignCustomerCode {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String region = OwnerRegion.of(owner);
27	        String code = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
28	        owner.setCustomerCode(CustomerCode.deduplicate(code, takenCodes(ownerRepository)::contains));
29	    }
30	
31	    /** The customer codes already in use by existing owners. */
32	    private static Set<String> takenCodes(OwnerRepository ownerRepository) {
33	        Set<String> taken = new HashSet<>();
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (existing.getCustomerCode() != null) {
36	                taken.add(existing.getCustomerCode());
37	            }
38	        }
39	        return taken;
40	    }
41	}
