1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	import org.springframework.samples.petclinic.util.IdentityKey;
9	
10	/**
11	 * The duplicate block: rejects a create that re-registers the same identity as an existing
12	 * owner, as a 409 via {@link DuplicateIdentityException}. An owner's identity is its
13	 * {@link IdentityKey} — the SHA-256 digest over normalized telephone, lower-cased email and
14	 * the Soundex of the last name — and a request whose key matches a non-deleted owner's is
15	 * the same person registering twice.
16	 *
17	 * <p>Because the telephone is part of the key, two owners sharing a last name and postcode
18	 * but with <em>different</em> telephones are distinct identities: the second is allowed
19	 * through, created and flagged as a soft duplicate (see {@link AssignPossibleDuplicate}). A
20	 * request that opts in with {@code sharesHousehold=true} is a declared household member and
21	 * bypasses the block (and is left unflagged).
22	 *
23	 * <p>Runs after the telephone and email are normalized (matching the stored form) and after
24	 * the disposable-email blocklist, and before {@link BuildOwner}, so a collision is caught
25	 * before any owner is built or saved.
26	 */
27	public class EnsureUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return;
33	        }
34	        String identityKey = IdentityKey.of(request.getTelephone(), request.getEmail(), request.getLastName());
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (Boolean.TRUE.equals(existing.getDeleted())) {
37	                continue; // a soft-deleted owner no longer holds its identity
38	            }
39	            if (identityKey.equals(IdentityKey.of(existing))) {
40	                throw new DuplicateIdentityException(identityKey);
41	            }
42	        }
43	    }
44	}
