3	/**
4	 * The owner's marketing segment, formatted {@code <TIER>_<AREA>}: the membership tier and
5	 * the region area combined into one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
6	 * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
7	 *
8	 * <p>TIER is {@code PREMIUM} at membership level 3 or above (see {@link MembershipLevel}),
9	 * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known
10	 * region — any region other than {@link CityRegion#UNKNOWN}, i.e. NSW, VIC or QLD (see
11	 * {@link OwnerRegion}) — otherwise {@code REGIONAL}.
12	 */
13	public final class OwnerSegment {
14	
15	    /** Lowest membership level whose tier is {@code PREMIUM}. */
16	    private static final int PREMIUM_LEVEL = 3;
17	
18	    private OwnerSegment() {
19	    }
20	
21	    /**
22	     * The segment for the given membership level and locality.
23	     *
24	     * @param membershipLevel the owner's membership level (see {@link MembershipLevel})
25	     * @param locality        the owner's locality (see {@link OwnerRegion})
26	     * @return the {@code <TIER>_<AREA>} segment
27	     */
28	    public static String of(int membershipLevel, String locality) {
29	        return tier(membershipLevel) + "_" + area(locality);
30	    }
31	
32	    private static String tier(int membershipLevel) {
33	        return membershipLevel >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
34	    }
35	
36	    private static String area(String locality) {
37	        return CityRegion.UNKNOWN.equals(locality) ? "REGIONAL" : "METRO";
38	    }
39	}
