5	
6	/**
7	 * Fiscal-year calendar for owner date-derived values. The fiscal year starts on 1 July
8	 * and is named after the calendar year in which it begins, so 1 July 2026 through 30 June
9	 * 2027 is fiscal year 2026 ("FY26"). This single primitive backs everything derived on a
10	 * fiscal-year basis: the owner's {@code fiscalYear} field, the membership number's year
11	 * segment ({@code -M<YY>}) and the tenure count in
12	 * {@link MembershipPoints}.
13	 */
14	public final class FiscalYear {
15	
16	    /** The month in which each fiscal year starts (1 July). */
17	    public static final Month START = Month.JULY;
18	
19	    private FiscalYear() {
20	    }
21	
22	    /** The fiscal year a date falls in, as the calendar year in which that fiscal year
23	     *  starts (e.g. 2026 for any date from 1 July 2026 to 30 June 2027). */
24	    public static int of(LocalDate date) {
25	        int year = date.getYear();
26	        return date.getMonthValue() >= START.getValue() ? year : year - 1;
27	    }
28	
29	    /** The last two digits of a date's fiscal year, zero-padded (e.g. "26"). */
30	    public static String shortLabel(LocalDate date) {
31	        return String.format("%02d", of(date) % 100);
32	    }
33	
34	    /** A date's fiscal year as an {@code FY<YY>} label (e.g. "FY26"). */
35	    public static String label(LocalDate date) {
36	        return "FY" + shortLabel(date);
37	    }
38	
39	    /** The whole fiscal years elapsed from {@code from} to {@code to} — the number of
40	     *  1 July boundaries crossed between them, negative when {@code to} precedes
41	     *  {@code from}. */
42	    public static int elapsed(LocalDate from, LocalDate to) {
43	        return of(to) - of(from);
44	    }
45	}
