import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.MembershipLevel;

/**
 * Emits an audit trail entry for a successfully created owner. Runs after
 * {@link SaveOwner} (so the owner has its generated id) and before the response, logging
 * the owner id, customer code, registration date, membership level and membership number
 * to the dedicated {@code AUDIT} logger.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner) {
        AUDIT.info("Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                MembershipLevel.of(owner), owner.getMembershipNumber());
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Immutable structured audit event recording that an owner was created. Serialised to JSON
 * and emitted to the {@code AUDIT} logger by {@link OwnerEventPublisher}.
 *
 * <p>{@code customerCode} carries the owner's <em>current primary identifier</em>
 * (see {@link org.springframework.samples.petclinic.model.Owner#getPrimaryIdentifier()}),
 * so it follows the identifier automatically if it is later unified into a member id.
 *
 * @param seq             monotonically increasing sequence, unique across creates
 * @param ownerId         the created owner's generated id
 * @param customerCode    the owner's current primary identifier at creation time
 * @param membershipLevel the owner's computed membership level at creation time
 * @param event           the event type, always {@link #EVENT_TYPE}
 */
public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel,
        String event) {

    /** The {@code event} discriminator for an owner-created event. */
    public static final String EVENT_TYPE = "OWNER_CREATED";
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps a newly built owner with the effective registration date resolved by
 * {@link ResolveRegistrationDate}. Runs after {@link BuildOwner} and mutates the built
 * owner in place, overwriting whatever date the request body mapped in, so the owner is
 * stored and returned with the adjusted business day and later steps (e.g.
 * {@link AssignMembershipNumber}) derive their values from it.
 */
public class ApplyRegistrationDate {

    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
        owner.setRegistrationDate(registrationDate);
    }
}

package org.springframework.samples.petclinic.util;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The canonical region ("locality") of an owner: the region derived from its postcode
 * first (see {@link PostcodeRange#regionOf(String)}), falling back to the city-to-region
 * table when the postcode is absent or in no known range, or {@link CityRegion#UNKNOWN}
 * for a city not in the table.
 *
 * <p>This region is the {@code REGION} segment of the owner's customer-code identity (see
 * {@link CustomerCode}); the identity is built from it on creation and the locality read
 * back off it, so there is one region concept rather than two derivations that could drift.
 */
public final class OwnerRegion {

    private OwnerRegion() {
    }

    /** The region for the given owner, derived from its postcode then its city. */
    public static String of(Owner owner) {
        String byPostcode = PostcodeRange.regionOf(owner.getPostcode());
        return byPostcode != null ? byPostcode : CityRegion.localityOf(owner.getCity());
    }
}

package org.springframework.samples.petclinic.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Shared SHA-256 hex digest, so the several identity values derived from a hash (the
 * customer code's {@code HASH8} segment and the household id) all agree on the algorithm
 * and encoding instead of each carrying their own copy.
 */
public final class Sha256 {

    private Sha256() {
    }

    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    public static String hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}

